using Key = std::string;
using Ptr = std::shared_ptr<Conn>;

static std::unordered_map<Key, Ptr> registry;
static std::mutex m;                      /* guards both the map and the slots */

Ptr conn_for(const Key& k) {
    std::lock_guard<std::mutex> g(m);
    auto [it, inserted] = registry.try_emplace(k, nullptr);
    if (inserted) it->second = std::make_shared<Conn>(k);  /* created once per key */
    return it->second;
}
